api.look('noir');
const cx=api.w/2, cy=340, k=api.seg(t,0,1.4);
const beat=1+0.05*Math.pow(Math.max(0,Math.sin(t*6)),3);
api.glow(cx,cy,170,{c:'accent'});
api.path('M0 70 C-110 -10 -90 -90 -40 -80 C-15 -75 0 -55 0 -45 C0 -55 15 -75 40 -80 C90 -90 110 -10 0 70 Z',{x:cx,y:cy,s:1.9*beat,c:'accent',w:4,fill:'accent',k});
api.text('Heart',cx,cy+210,{size:36,align:'center',k:api.seg(t,1,2)});
api.say('The heart is a pump',0.3,3.5);

api.look('noir');
const cx=api.w/2, cy=340;
const beat=1+0.03*Math.pow(Math.max(0,Math.sin(t*6)),3);
api.path('M0 120 C-170 -10 -150 -150 -60 -140 C-20 -135 0 -100 0 -90 C0 -100 20 -135 60 -140 C150 -150 170 -10 0 120 Z',{x:cx,y:cy,s:1.15*beat,c:'accent',w:4,fill:'#3a1420'});
api.line(cx,cy-100,cx,cy+110,{c:'fg',w:3,k:api.seg(t,0,1)});
api.line(cx-130,cy-10,cx+130,cy-10,{c:'fg',w:3,k:api.seg(t,0.5,1.5)});
api.text('Right atrium',cx-80,cy-60,{size:16,align:'center',c:'a2',k:api.seg(t,1.5,2.2)});
api.text('Left atrium',cx+80,cy-60,{size:16,align:'center',c:'accent',k:api.seg(t,2,2.7)});
api.text('Right ventricle',cx-70,cy+50,{size:16,align:'center',c:'a2',k:api.seg(t,2.5,3.2)});
api.text('Left ventricle',cx+70,cy+50,{size:16,align:'center',c:'accent',k:api.seg(t,3,3.7)});
api.callout('Four rooms',cx,cy-140,cx+60,cy-230,{k:api.seg(t,3.5,4.5)});
api.say('Four chambers, two sides',0.3,5.5);

api.look('noir');
const cx=api.w/2, cy=330;
const lung=[cx-110,cy-190], body=[cx+110,cy+190];
const H=api.node(cx,cy,110,90,'Heart',{icon:'heart',k:api.seg(t,0,0.8),c:'accent'});
const L=api.node(cx-110,cy-190,150,70,'Lungs',{k:api.seg(t,0.5,1.3),c:'a2'});
const B=api.node(cx+110,cy+190,150,70,'Body',{k:api.seg(t,1,1.8),c:'accent'});
api.link(H,L,{k:api.seg(t,1.8,3),label:'blue blood',flow:t,bend:-0.4,c:'a2'});
api.link(L,H,{k:api.seg(t,3,4.2),label:'red blood',flow:t,bend:-0.4,c:'accent'});
api.link(H,B,{k:api.seg(t,4.2,5.4),label:'to body',flow:t,bend:0.4,c:'accent'});
api.say('Lungs add oxygen, body uses it',0.3,6.5);

api.look('noir');
const cx=api.w/2, cy=300;
const beat=1+0.08*Math.pow(Math.max(0,Math.sin(t*6)),3);
api.shape('heart',cx,cy,200*beat,{c:'accent',fill:'accent'});
api.counter(100000,cx,cy+190,{k:api.seg(t,0.5,3),suf:' beats a day',size:30});
api.counter(7500,cx,cy+260,{k:api.seg(t,2,4.5),suf:' litres pumped',size:30,c:'a2'});
api.say('Beating all day, every day',0.3,5.5);
